CREATE MATERIALIZED VIEW mvwa_mv35 AS SELECT id FROM s.t;
CREATE UNIQUE INDEX ON mvwa_mv35 (id);
REFRESH MATERIALIZED VIEW CONCURRENTLY mvwa_mv35

CREATE MATERIALIZED VIEW mvwa_mv66a AS SELECT id FROM s.t WITH NO DATA;
CREATE MATERIALIZED VIEW mvwa_mv66b AS SELECT id FROM s.t WITH NO DATA;
DROP MATERIALIZED VIEW mvwa_mv66a, mvwa_mv66b

CREATE MATERIALIZED VIEW mvwa_mv67a AS SELECT id FROM s.t WITH NO DATA;
CREATE MATERIALIZED VIEW mvwa_mv67b AS SELECT id FROM s.t WITH NO DATA;
DROP MATERIALIZED VIEW mvwa_mv67a, mvwa_mv67b CASCADE

CREATE MATERIALIZED VIEW mvwa_depbase AS SELECT id FROM s.t WITH NO DATA;
CREATE MATERIALIZED VIEW mvwa_dep AS SELECT * FROM mvwa_depbase WITH NO DATA;
DROP MATERIALIZED VIEW mvwa_depbase CASCADE

CREATE MATERIALIZED VIEW mvwa_mv70 AS SELECT id, name FROM s.t WITH NO DATA;
ALTER MATERIALIZED VIEW mvwa_mv70 SET (fillfactor=75);
DROP MATERIALIZED VIEW mvwa_mv70

CREATE MATERIALIZED VIEW mvwa_mv71 AS SELECT id FROM s.t WITH NO DATA;
REFRESH MATERIALIZED VIEW mvwa_mv71;
DROP MATERIALIZED VIEW mvwa_mv71

CREATE MATERIALIZED VIEW mvwa_mv96 AS SELECT id FROM s.t WITH NO DATA;
ALTER MATERIALIZED VIEW mvwa_mv96 RENAME TO mvwa_mv96_renamed;
DROP MATERIALIZED VIEW mvwa_mv96_renamed

CREATE MATERIALIZED VIEW mvwa_mv134 AS SELECT id FROM s.t WITH NO DATA;
CREATE INDEX mvwa_idx134 ON mvwa_mv134 (id);
ALTER MATERIALIZED VIEW mvwa_mv134 CLUSTER ON mvwa_idx134

CREATE MATERIALIZED VIEW mvwa_mv139 AS SELECT id FROM s.t;
REFRESH MATERIALIZED VIEW mvwa_mv139 WITH DATA;
REFRESH MATERIALIZED VIEW mvwa_mv139 WITH NO DATA

CREATE MATERIALIZED VIEW mvwa_mv159 AS SELECT id FROM s.t WITH NO DATA;
ALTER MATERIALIZED VIEW IF EXISTS mvwa_mv159 SET SCHEMA s;
DROP MATERIALIZED VIEW s.mvwa_mv159
